// Extrai e normaliza campos do item Apify Google Maps
const apify = $input.item.json;

// Telefone limpo (remove formatação)
const phone = (apify.phone || apify.phoneUnformatted || '').replace(/\D/g, '');

// Website
const website = apify.website || null;

// Detecta presença em redes (via URL do website ou dados Apify)
const hasWebsite = !!(website && website.trim() !== '');
const hasInstagram = !!(apify.website && apify.website.includes('instagram.com'));
const hasFacebook = !!(apify.website && apify.website.includes('facebook.com'));

// Nome normalizado para busca CNPJ (remove sufixos jurídicos comuns)
const cleanName = (apify.title || '')
  .replace(/\s*(LTDA|ME|EPP|SA|S\.A\.|EIRELI|MEI|SS)\s*\.?$/i, '')
  .replace(/[^a-zA-ZÀ-ÿ0-9\s]/g, ' ')
  .trim()
  .substring(0, 60);

return [{
  json: {
    // Dados originais do Apify
    apifyData: apify,
    // Campos normalizados para Supabase
    business_name: apify.title || 'Sem nome',
    phone: phone || null,
    website: hasWebsite ? website : null,
    address_full: apify.address || null,
    address_city: apify.city || null,
    address_state: apify.state || $('Preparar Config').item.json.state,
    address_postal_code: apify.postalCode || null,
    google_maps_url: apify.url || null,
    google_rating: parseFloat(apify.totalScore) || null,
    google_reviews_count: parseInt(apify.reviewsCount) || null,
    google_category: apify.categoryName || null,
    has_website: hasWebsite,
    has_instagram: hasInstagram,
    has_facebook: hasFacebook,
    has_google_mybusiness: true,  // está no Google Maps = tem GMB
    // Para busca de CNPJ
    cnpjSearchName: cleanName,
    cnpjSearchCity: apify.city || $('Preparar Config').item.json.city,
    cnpjSearchState: apify.state || $('Preparar Config').item.json.state,
    // Contexto do workflow
    projectId: $('Salvar Run ID Apify').item.json.projectId,
    apifyRunId: $('Salvar Run ID Apify').item.json.apifyRunId,
    supabaseUrl: $('Salvar Run ID Apify').item.json.supabaseUrl,
    supabaseKey: $('Salvar Run ID Apify').item.json.supabaseKey
  }
}];

// Normaliza resposta da Brasil API para os campos do Supabase
const cnpjData = $input.item.json;
const leadBase = $('Montar Dados Lead').item.json;

const cnpjClean = (cnpjData.cnpj || '').replace(/\.|\/|\-/g, '');

return [{
  json: {
    ...leadBase,
    // CNPJ enriquecido
    cnpj: cnpjClean || null,
    cnpj_razao_social: cnpjData.razao_social || null,
    cnpj_nome_fantasia: cnpjData.nome_fantasia || null,
    cnpj_situacao: cnpjData.descricao_situacao_cadastral || cnpjData.situacao_cadastral || null,
    cnpj_data_abertura: cnpjData.data_inicio_atividade || null,
    cnpj_capital_social: parseFloat(cnpjData.capital_social) || null,
    cnpj_porte: cnpjData.descricao_porte || cnpjData.porte || null,
    cnpj_atividade_principal: cnpjData.cnae_fiscal_descricao || (cnpjData.atividade_principal && cnpjData.atividade_principal[0] && cnpjData.atividade_principal[0].text) || null,
    cnpj_municipio: cnpjData.municipio || null,
    cnpj_uf: cnpjData.uf || null,
    cnpj_email: cnpjData.email || null,
    cnpj_telefone: cnpjData.ddd_telefone_1 || null,
    cnpj_raw: cnpjData,
    // Atualiza email/telefone se veio do CNPJ e não tinha do Google
    email: leadBase.email || cnpjData.email || null,
    phone: leadBase.phone || (cnpjData.ddd_telefone_1 || '').replace(/\D/g,'') || null,
    status: 'ENRIQUECIDO',
    enriched_at: new Date().toISOString()
  }
}];

// Monta o bloco de dados da empresa para o prompt do Analista SDR
// Funciona tanto com CNPJ quanto sem ele
const d = $input.item.json;

const linhas = [];

// Google Maps
linhas.push(`Nome: ${d.business_name || 'N/A'}`);
if (d.google_category) linhas.push(`Categoria: ${d.google_category}`);
if (d.address_city) linhas.push(`Cidade: ${d.address_city}${d.address_state ? ' / ' + d.address_state : ''}`);
if (d.google_rating) linhas.push(`Avaliação Google: ${d.google_rating} ⭐ (${d.google_reviews_count || 0} avaliações)`);
if (d.website) linhas.push(`Website: ${d.website}`);
else linhas.push('Website: Não encontrado no Google Maps');
linhas.push(`Instagram detectado: ${d.has_instagram ? 'Sim (link no perfil)' : 'Não detectado'}`);
linhas.push(`Facebook detectado: ${d.has_facebook ? 'Sim' : 'Não detectado'}`);
linhas.push(`Google My Business: ${d.has_google_mybusiness ? 'Sim (listado no Maps)' : 'Não'}`);

// CNPJ (se disponível)
if (d.cnpj) {
  linhas.push('');
  linhas.push('--- Dados Receita Federal ---');
  linhas.push(`CNPJ: ${d.cnpj}`);
  if (d.cnpj_situacao) linhas.push(`Situação CNPJ: ${d.cnpj_situacao}`);
  if (d.cnpj_data_abertura) linhas.push(`Data de abertura: ${d.cnpj_data_abertura}`);
  if (d.cnpj_porte) linhas.push(`Porte: ${d.cnpj_porte}`);
  if (d.cnpj_capital_social) linhas.push(`Capital social: R$ ${Number(d.cnpj_capital_social).toLocaleString('pt-BR', {minimumFractionDigits:2})}`);
  if (d.cnpj_atividade_principal) linhas.push(`Atividade principal: ${d.cnpj_atividade_principal}`);
  if (d.cnpj_email) linhas.push(`E-mail CNPJ: ${d.cnpj_email}`);
  if (d.cnpj_telefone) linhas.push(`Telefone CNPJ: ${d.cnpj_telefone}`);
} else {
  linhas.push('');
  linhas.push('--- Dados Receita Federal ---');
  linhas.push('CNPJ: Não encontrado na busca automatizada');
}

const dadosEmpresa = linhas.join('\n');

const systemPrompt = `Você é um Analista de Inteligência Comercial especializado em identificar oportunidades de marketing digital para pequenas e médias empresas no Brasil.\n\nSua única função nesta chamada é: receber dados públicos de uma empresa, analisar sua presença digital e potencial de compra de serviços de marketing, e devolver um JSON estruturado com score e dores identificadas.\n\nVocê NÃO deve conversar. Você NÃO deve perguntar nada. Responda SOMENTE com JSON válido.`;

const userPrompt = `Analise a empresa abaixo e classifique a oportunidade de venda de serviços de marketing digital.\n\n## DADOS DA EMPRESA\n\n${dadosEmpresa}\n\n---\n\n## CRITÉRIOS DE CLASSIFICAÇÃO\n\n### SCORE A — Alta Oportunidade (prioridade máxima)\n- CNPJ ATIVO há mais de 2 anos\n- Avaliação Google entre 3,0 e 4,3\n- Mais de 15 avaliações Google\n- Website ausente ou com sinais de abandono\n- Instagram/Facebook ausente ou com pouco engajamento\n- Porte ME ou EPP\n- Nicho: estética, saúde, alimentação, fitness, educação, automotivo, pet, varejo local\n\n### SCORE B — Oportunidade Média\n- Empresa ativa com presença digital básica mas inconsistente\n- Porte ME/EPP com sinais de investimento leve em marketing\n- Dados insuficientes para classificar como A com confiança\n\n### SCORE C — Baixa Oportunidade (não prospectar)\n- CNPJ baixado, suspenso ou com irregularidade\n- Grande porte ou capital social > R$ 500.000\n- Presença digital muito forte\n- Nicho sem fit: indústria, atacado B2B, imóveis de alto padrão\n- Empresa claramente fechada ou endereço inválido\n\n## SAÍDA ESPERADA (JSON puro, sem markdown)\n\n{\n  "score": "A",\n  "score_rationale": "Máximo 2 frases explicando o score.",\n  "digital_gap_score": 85,\n  "identified_pains": ["dor 1", "dor 2", "dor 3"],\n  "improvement_opportunities": ["oportunidade 1", "oportunidade 2"],\n  "first_message_angle": "Gancho concreto para o 1º contato frio.",\n  "discard_reason": null\n}`;

return [{
  json: {
    ...d,
    aiSystemPrompt: systemPrompt,
    aiUserPrompt: userPrompt
  }
}];

// Extrai JSON da resposta do Claude e mescla com dados do lead
const apiResponse = $input.item.json;
const leadData = $('Preparar Prompt IA').item.json;

let aiResult = {};
try {
  // Extrai o texto da resposta
  const rawText = apiResponse.content?.[0]?.text || apiResponse.error?.message || '';
  // Tenta parsear como JSON (o modelo deve retornar só JSON)
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Resposta não contém JSON válido: ' + rawText.substring(0, 100));
  }
} catch (e) {
  // Fallback: score B com erro registrado
  aiResult = {
    score: 'B',
    score_rationale: 'Erro ao parsear resposta da IA: ' + e.message,
    digital_gap_score: 50,
    identified_pains: ['Análise automática falhou — revisar manualmente'],
    improvement_opportunities: ['Executar análise manual'],
    first_message_angle: 'Verificar manualmente',
    discard_reason: null
  };
}

// Tokens e custo estimado (Haiku: $0.80/M input, $4/M output)
const promptTokens = apiResponse.usage?.input_tokens || 0;
const completionTokens = apiResponse.usage?.output_tokens || 0;
const costUsd = (promptTokens * 0.0000008) + (completionTokens * 0.000004);

return [{
  json: {
    // Todos os dados do lead
    ...leadData,
    // Score e análise IA
    score: aiResult.score || 'B',
    score_rationale: aiResult.score_rationale || null,
    digital_gap_score: parseInt(aiResult.digital_gap_score) || null,
    identified_pains: JSON.stringify(aiResult.identified_pains || []),
    improvement_opportunities: JSON.stringify(aiResult.improvement_opportunities || []),
    first_message_angle: aiResult.first_message_angle || null,
    discard_reason: aiResult.discard_reason || null,
    ai_analysis_raw: JSON.stringify(aiResult),
    // Metadados IA
    aiPromptTokens: promptTokens,
    aiCompletionTokens: completionTokens,
    aiCostUsd: costUsd,
    aiModelUsed: 'claude-haiku-4-5',
    // Status final
    status: 'ANALISADO',
    analyzed_at: new Date().toISOString()
  }
}];

// Resumo do run para exibição na tela do n8n
const allItems = $input.all();

const summary = {
  mensagem: '✅ Coleta e análise da Fase 1 concluída!',
  timestamp: new Date().toISOString(),
  total_processados: allItems.length,
  dica: 'Acesse a view sdr_validation_panel no Supabase para validar os scores manualmente.',
  proximos_passos: [
    '1. Abra o Supabase → SQL Editor → SELECT * FROM sdr_validation_panel LIMIT 20',
    '2. Valide 20 leads score A manualmente (veja sdr/prompts/analista-sdr.md)',
    '3. Atualize manual_score_ok = true/false em cada lead revisado',
    '4. Se taxa de acerto < 80%, ajuste os critérios no prompt e reanalise'
  ]
};

console.log(JSON.stringify(summary, null, 2));
return [{ json: summary }];
